package com.hardcraft.world;
import java.nio.file.Path;import java.util.*;import java.util.logging.Level;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.bukkit.plugin.java.JavaPlugin;
public final class HardCraftWorld extends JavaPlugin implements CommandExecutor{
 private ClaimService claims;private int min,max,limit,maxBlocks;
 public void onEnable(){try{saveDefaultConfig();min=getConfig().getInt("claims.min-radius");max=getConfig().getInt("claims.max-radius");limit=getConfig().getInt("claims.max-per-player");maxBlocks=getConfig().getInt("claims.max-blocks");if(min<1||max<min||limit<1)throw new IllegalArgumentException("invalid claim limits");JavaPlugin core=(JavaPlugin)Objects.requireNonNull(getServer().getPluginManager().getPlugin("HardCraftCore"),"Core unavailable");Path db=core.getDataFolder().toPath().resolve("hardcraft.db");ClaimRepository repo=new ClaimRepository(db);repo.migrate();claims=new ClaimService(repo);getServer().getPluginManager().registerEvents(new ProtectionListener(claims,getConfig().getBoolean("pvp-enabled")),this);Objects.requireNonNull(getCommand("claim")).setExecutor(this);Objects.requireNonNull(getCommand("claimadmin")).setExecutor(this);getLogger().info("HardCraftWorld enabled; claims="+claims.snapshot().size()+"; safe PvP="+!getConfig().getBoolean("pvp-enabled"));new StagingProbe(this,claims).run();}catch(RuntimeException e){getLogger().log(Level.SEVERE,"HardCraftWorld failed",e);getServer().getPluginManager().disablePlugin(this);}}
 public boolean onCommand(CommandSender sender,Command cmd,String label,String[] a){if(!(sender instanceof Player p)){sender.sendMessage("Players only");return true;}try{if(cmd.getName().equals("claimadmin")){if(a.length==2&&a[0].equalsIgnoreCase("delete")){respond(p,claims.delete(Long.parseLong(a[1]),p.getUniqueId(),true));return true;}return false;}if(a.length==0||a[0].equalsIgnoreCase("info")){var c=claims.at(p.getWorld().getUID().toString(),p.getLocation().getBlockX(),p.getLocation().getBlockZ());p.sendMessage(c.map(x->"Claim #"+x.id()+" owner="+x.owner()+" trusted="+x.trusted().size()).orElse("Unclaimed"));return true;}if(a[0].equalsIgnoreCase("create")&&a.length==2){int r=Integer.parseInt(a[1]);if(r<min||r>max||(2*r+1L)*(2*r+1)>maxBlocks)throw new IllegalArgumentException("radius must be "+min+"-"+max);respond(p,claims.create(p.getUniqueId(),p.getWorld().getUID().toString(),p.getLocation().getBlockX(),p.getLocation().getBlockZ(),r,limit));return true;}Claim here=claims.at(p.getWorld().getUID().toString(),p.getLocation().getBlockX(),p.getLocation().getBlockZ()).orElseThrow(()->new IllegalArgumentException("stand inside claim"));if(a[0].equalsIgnoreCase("delete")){respond(p,claims.delete(here.id(),p.getUniqueId(),false));return true;}if((a[0].equalsIgnoreCase("trust")||a[0].equalsIgnoreCase("untrust"))&&a.length==2){var target=getServer().getOfflinePlayer(a[1]);if(!target.hasPlayedBefore()&&!target.isOnline())throw new IllegalArgumentException("unknown player");respond(p,claims.trust(here.id(),target.getUniqueId(),p.getUniqueId(),a[0].equalsIgnoreCase("trust")));return true;}return false;}catch(Exception e){p.sendMessage("Claim rejected: "+e.getMessage());return true;}}
 private void respond(CommandSender s,java.util.concurrent.CompletableFuture<?> f){f.thenRun(()->getServer().getScheduler().runTask(this,()->s.sendMessage("Claim updated"))).exceptionally(e->{getServer().getScheduler().runTask(this,()->s.sendMessage("Claim rejected: "+e.getCause().getMessage()));return null;});}
 public void onDisable(){if(claims!=null)claims.close();}
}